import {chapters} from './catalog.js';
import {makeRun,recordAnswer,advance,freshProgress,updateProgress,validRun} from './engine.js';
const main=document.querySelector('#main');
let chapter=chapters[0],questions=[],topics=[],notes=[],bank=new Map(),KEY='',storageAvailable=true,progress=freshProgress(),run=null,view='home';
function loadChapter(id){
 chapter=chapters.find(c=>c.id===id)||chapters[0];
 ({questions,topics,notes}=chapter);bank=new Map(questions.map(q=>[q.id,q]));KEY=chapter.storageKey;
 progress=freshProgress();run=null;
 try{const saved=JSON.parse(localStorage.getItem(KEY));if(saved?.progress?.version===1){const p=saved.progress;progress={...freshProgress(),...p,seen:Object.fromEntries(Object.entries(p.seen||{}).filter(([id,v])=>bank.has(id)&&typeof v==='boolean')),missed:Array.isArray(p.missed)?[...new Set(p.missed.filter(id=>bank.has(id)))]:[],bestScore:Number.isFinite(p.bestScore)&&p.bestScore>=0?p.bestScore:0,runs:Number.isInteger(p.runs)&&p.runs>=0?p.runs:0};if(validRun(saved.run,questions))run=saved.run;}}catch{storageAvailable=false;}
}
let initialChapter='ch1';try{initialChapter=localStorage.getItem('marketquest-selected-chapter')||'ch1';}catch{storageAvailable=false;}
loadChapter(initialChapter);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const mastered=()=>Object.values(progress.seen).filter(Boolean).length;
const topicName=id=>topics.find(t=>t.id===id)?.name||`Chapter ${chapter.number}`;
const sessionSaves=new Map();
function save(){sessionSaves.set(chapter.id,JSON.stringify({progress,run}));try{localStorage.setItem(KEY,JSON.stringify({progress,run}));}catch{storageAvailable=false;}}
function announce(message){document.querySelector('#announcement').textContent=message;}
function navigate(next){view=next;render();main.focus();window.scrollTo({top:0,behavior:'instant'});}
function render(){
 document.title=`MarketQuest — Chapter ${chapter.number}`;
 document.querySelector('.breadcrumb').textContent=`/ CHAPTER ${String(chapter.number).padStart(2,'0')}`;
 document.querySelector('.chapter-list').innerHTML=chapters.map(c=>`<button class="chapter-card chapter-choice ${c.id===chapter.id?'selected':''}" data-chapter="${c.id}" aria-pressed="${c.id===chapter.id}"><span class="live-dot"></span><span>CHAPTER ${String(c.number).padStart(2,'0')}<small>${c.short}</small></span><span class="chapter-arrow">${c.id===chapter.id?'✓':'↗'}</span></button>`).join('');

 document.querySelectorAll('[data-nav]').forEach(b=>b.classList.toggle('active',b.dataset.nav===(view==='notes'?'notes':'home')));
 document.querySelector('.save-label').innerHTML=`<span class="live-dot"></span> ${storageAvailable?'Progress saved on this browser':'Session only · storage unavailable'}`;
 main.innerHTML=(!storageAvailable?'<div class="storage-warning">Browser storage is unavailable. You can play, but progress may be lost when you close this page.</div>':'')+(view==='home'?home():view==='notes'?fieldNotes():view==='results'?results():quiz());
}
function home(){const count=mastered(),pct=Math.round(count/questions.length*100);return `
 <div class="page-heading"><div><p class="eyebrow">A SMALL SESSION. A BIG STEP FORWARD.</p><h1>Make knowledge stick.</h1><p class="subtitle">Your Chapter ${chapter.number} mission starts here. Learn it by playing it.</p></div><div class="date-chip">✳ &nbsp; CHAPTER ${String(chapter.number).padStart(2,'0')} / 05</div></div>
 ${run&&run.index<run.items.length?`<div class="resume-banner"><span><strong>A mission is in progress.</strong> ${run.answers.length}/${run.items.length} answered · ${run.score} XP</span><button class="btn dark" data-action="resume">Resume →</button></div>`:''}
 <section class="hero" aria-label="Chapter ${chapter.number} campaign"><div class="hero-copy"><div class="eyebrow">THE CHAPTER ${chapter.number} CAMPAIGN &nbsp; / &nbsp; ${questions.length} QUESTIONS</div><h2>${chapter.headline}</h2><p>${chapter.title}.<br>Six missions. Real business decisions. Your next level.</p><button class="btn" data-action="start" data-mode="campaign">${count?'Play the campaign':'Start the campaign'} <span>↗</span></button><span class="hero-meta">No timer. Just sharper thinking.</span></div><div class="hero-art" aria-hidden="true"><div class="orbital"></div><span class="art-star">✳</span><span class="art-dot"></span><div class="art-badge">BUILD YOUR MARKETING INSTINCT</div></div></section>
 <section class="stats" aria-label="Your progress"><div class="stat"><div class="stat-label">CHAPTER MASTERY <span class="stat-icon">◎</span></div><div class="stat-value">${pct}<small> %</small></div><div class="stat-detail">${count} of ${questions.length} latest answers correct</div></div><div class="stat"><div class="stat-label">BEST ROUND <span class="stat-icon">⚑</span></div><div class="stat-value">${progress.bestScore.toLocaleString()}<small> XP</small></div><div class="stat-detail">${progress.runs} completed ${progress.runs===1?'round':'rounds'}</div></div><div class="stat"><div class="stat-label">SECOND CHANCES <span class="stat-icon">↻</span></div><div class="stat-value">${progress.missed.length}<small> questions</small></div><div class="stat-detail">Missed concepts ready for a comeback</div></div></section>
 <div class="section-heading"><h2>Your mission map</h2><span>SIX MISSIONS · EIGHT QUESTIONS EACH</span></div><section class="missions" aria-label="Topic missions">${topics.map(t=>{const right=questions.filter(q=>q.topic===t.id&&progress.seen[q.id]===true).length;return `<button class="mission" data-action="start" data-mode="mission" data-topic="${t.id}"><div class="mission-top"><span class="mission-icon" aria-hidden="true">${t.icon}</span><span class="mission-tag">MISSION ${t.tag}</span></div><h3>${t.name}</h3><p>${t.description}</p><div class="mission-progress"><span style="width:${right/8*100}%"></span></div><div class="mission-bottom"><span>${right}/8 mastered</span><b aria-hidden="true">↗</b></div></button>`;}).join('')}</section>
 <div class="practice-row"><section class="practice-card"><span class="practice-icon" aria-hidden="true">ϟ</span><div><h3>Quick fire</h3><p>10 shuffled questions. A fresh mix each round.</p></div><button class="btn outline" data-action="start" data-mode="quick">Play ↗</button></section><section class="practice-card"><span class="practice-icon" aria-hidden="true">↻</span><div><h3>The comeback round</h3><p>${progress.missed.length?'Turn your missed concepts into confident answers.':'Miss a question? It will be waiting here.'}</p></div><button class="btn outline" data-action="start" data-mode="retry" ${progress.missed.length?'':'disabled'}>Retry ↗</button></section></div>
 <div class="section-heading"><span>100 XP per correct answer · streak bonus up to +100 XP · no time penalty</span><button class="text-button" data-nav="notes">Read field notes →</button></div>`;}
function fieldNotes(){return `<div class="page-heading"><div><p class="eyebrow">PAUSE. CONNECT. REMEMBER.</p><h1>Your field notes.</h1><p class="subtitle">Chapter ${chapter.number}: ${chapter.title}. The ideas behind the answers.</p></div><button class="btn dark" data-nav="home">Back to missions ↗</button></div><div class="notes-grid">${notes.map((n,i)=>`<article class="note"><div class="eyebrow">CONCEPT ${String(i+1).padStart(2,'0')}</div><h2>${n[0]}</h2><p>${n[1]}</p></article>`).join('')}</div><p class="note-foot">This is an independent study companion with original questions and hypothetical business examples, not a publisher test bank. Field notes summarize the selected chapter reviewer; use your assigned textbook and instructor’s materials for the full treatment.</p><div class="reset-row"><button class="text-button" data-action="reset">Reset local progress</button></div>`;}
function quiz(){if(!run||run.index>=run.items.length)return results();const q=bank.get(run.items[run.index].id),response=run.answers[run.index],answered=!!response;return `
 <div class="quiz-top"><button class="text-button" data-nav="home">← Save & return to missions</button><span class="run-label">${run.mode==='quick'?'QUICK FIRE':run.mode==='retry'?'THE COMEBACK ROUND':run.mode==='mission'?'TOPIC MISSION':`CHAPTER ${chapter.number} CAMPAIGN`}</span></div>
 <div class="quiz-layout"><section class="question-card"><div class="question-meta"><span>${esc(topicName(q.topic)).toUpperCase()}</span><span>QUESTION ${run.index+1} / ${run.items.length}</span></div><div class="track" role="progressbar" aria-label="Round progress" aria-valuemin="0" aria-valuemax="${run.items.length}" aria-valuenow="${run.answers.length}"><span style="width:${run.answers.length/run.items.length*100}%"></span></div><p class="eyebrow">${q.topic.startsWith('cases')?'A DECISION FOR YOUR DESK':'ONE QUESTION. ONE CLEARER CONCEPT.'}</p><h1 id="question">${esc(q.prompt)}</h1><div class="answer-list" role="group" aria-labelledby="question">${run.items[run.index].order.map((option,i)=>{const correct=answered&&option===q.answer,wrong=answered&&option===response.choice&&!response.correct;return `<button class="answer${correct?' correct':''}${wrong?' wrong':''}" data-answer="${option}" ${answered?'disabled':''}><span class="answer-key">${i+1}</span><span>${esc(q.options[option])}</span>${correct?'<span class="answer-mark">✓ Correct</span>':wrong?'<span class="answer-mark">× Your pick</span>':''}</button>`;}).join('')}</div>
 ${answered?`<div class="explanation ${response.correct?'':'wrong'}" role="status"><strong>${response.correct?`Well reasoned. +${response.earned} XP`:'A useful miss. Here’s the distinction.'}</strong><p>${esc(q.explanation)}</p></div>`:''}<div class="quiz-bottom"><span class="key-hint">${answered?'Press Enter to continue':'Use keys 1–4 to choose · no timer'}</span><button class="btn dark" data-action="next" ${answered?'':'disabled'}>${run.index+1===run.items.length?'See your results':'Next question'} →</button></div></section><aside class="run-panel" aria-label="Round statistics"><p class="eyebrow">THIS ROUND</p><div class="run-score">${run.score}<small style="font-size:11px"> XP</small></div><dl><div><dt>Streak</dt><dd>${run.streak} 🔥</dd></div><div><dt>Correct</dt><dd>${run.answers.filter(a=>a.correct).length}/${run.answers.length}</dd></div><div><dt>Best streak</dt><dd>${run.bestStreak}</dd></div></dl><p class="coach">Every answer has a reason.<br>Take your time with the explanation — that’s where the learning happens.</p></aside></div>`;}
function results(){if(!run)return home();const right=run.answers.filter(a=>a.correct).length,accuracy=Math.round(right/run.items.length*100),missed=run.answers.filter(a=>!a.correct).length;const title=accuracy===100?'A perfect run.':accuracy>=80?'Your instincts are sharpening.':accuracy>=50?'You’re building the foundation.':'Every attempt is a starting point.';return `<section class="result-hero"><p class="eyebrow">ROUND COMPLETE · ${esc(run.mode==='mission'?topicName(run.topic):`CHAPTER ${chapter.number}`)}</p><div class="result-star" aria-hidden="true">${accuracy===100?'✳':'◎'}</div><h1>${title}</h1><p>${missed?`${missed} ${missed===1?'concept is':'concepts are'} ready for a second look. Review the reasoning below.`:'You answered every question correctly. Try another mission to keep the ideas fresh.'}</p><div class="result-stats"><div><strong>${run.score}</strong><span>XP EARNED</span></div><div><strong>${accuracy}%</strong><span>${right}/${run.items.length} CORRECT</span></div><div><strong>${run.bestStreak}</strong><span>BEST STREAK</span></div></div><div class="result-actions"><button class="btn" data-nav="home">Mission map ↗</button>${progress.missed.length?'<button class="btn outline" data-action="start" data-mode="retry">Retry missed concepts ↻</button>':'<button class="btn outline" data-action="start" data-mode="quick">Try quick fire ↗</button>'}</div></section><div class="section-heading"><h2>Your round, unpacked.</h2><span>OPEN ANY QUESTION TO REVIEW</span></div>${run.answers.map(a=>{const q=bank.get(a.id);return `<details><summary><span class="review-label ${a.correct?'good':'bad'}">${a.correct?'✓ CORRECT':'↻ REVISIT'}</span>${esc(q.prompt)}</summary><p><b>Your answer:</b> ${esc(q.options[a.choice])}<br><b>Correct answer:</b> ${esc(q.options[q.answer])}</p><p>${esc(q.explanation)}</p></details>`;}).join('')}`;}
function switchChapter(id){
 if(!chapters.some(c=>c.id===id)||id===chapter.id)return;
 save();loadChapter(id);
 if(sessionSaves.has(id)){const cached=JSON.parse(sessionSaves.get(id));progress=cached.progress;run=cached.run;}
 try{localStorage.setItem('marketquest-selected-chapter',chapter.id);}catch{storageAvailable=false;}
 navigate('home');announce(`Chapter ${chapter.number} selected. Each chapter keeps its own progress.`);
}
function start(mode,topic){if(run&&run.index<run.items.length&&!confirm('Start a new round? Your completed answers stay saved, but this unfinished round will be replaced.'))return;const next=makeRun(questions,{mode,topic:topic||null,missed:progress.missed});if(!next.items.length){announce('No missed questions to retry.');return;}run=next;save();navigate('quiz');}
function select(choice){if(view!=='quiz'||!run||run.index>=run.items.length)return;const q=bank.get(run.items[run.index].id),next=recordAnswer(run,q,choice);if(next===run)return;run=next;progress=updateProgress(progress,q,choice);save();render();document.querySelector('[data-action="next"]')?.focus();}
function next(){if(!run)return;const advanced=advance(run);if(advanced===run)return;run=advanced;if(run.index===run.items.length){progress.runs++;progress.bestScore=Math.max(progress.bestScore,run.score);save();navigate('results');}else{save();navigate('quiz');}}
function reset(){if(!confirm(`Erase this browser’s Chapter ${chapter.number} progress, best score, missed questions, and saved round? Other chapters will be kept.`))return;progress=freshProgress();run=null;save();navigate('home');announce('Local progress reset.');}
document.addEventListener('click',e=>{const b=e.target.closest('button,a.brand');if(!b||b.disabled)return;if(b.matches('a.brand')){e.preventDefault();navigate('home');}else if(b.dataset.chapter)switchChapter(b.dataset.chapter);else if(b.dataset.nav)navigate(b.dataset.nav);else if(b.dataset.answer!==undefined)select(Number(b.dataset.answer));else if(b.dataset.action==='start')start(b.dataset.mode,b.dataset.topic);else if(b.dataset.action==='resume')navigate('quiz');else if(b.dataset.action==='next')next();else if(b.dataset.action==='reset')reset();});
document.addEventListener('keydown',e=>{if(view!=='quiz'||e.altKey||e.ctrlKey||e.metaKey||e.repeat)return;if(/^[1-4]$/.test(e.key)){e.preventDefault();const item=run?.items[run.index];if(item)select(item.order[Number(e.key)-1]);}else if(e.key==='Enter'&&run?.answers[run.index]&&!e.target.closest('button,a,summary')){e.preventDefault();next();}});
render();
